import typing as t
from queue import Empty, Queue

from dlt.common import logger


# Please read more at https://mypy.readthedocs.io/en/stable/runtime_troubles.html#not-generic-runtime
T = t.TypeVar("T")

if t.TYPE_CHECKING:

    class _Queue(Queue[T]):
        pass

else:

    class _Queue(Queue, t.Generic[T]):
        pass


class QueueClosedError(Exception):
    pass


class ScrapingQueue(_Queue[T]):
    def __init__(
        self,
        maxsize: int = 0,
        batch_size: int = 10,
        read_timeout: float = 1.0,
    ) -> None:
        super().__init__(maxsize)
        self.batch_size = batch_size
        self.read_timeout = read_timeout
        self._is_closed = False

    def get_batches(self) -> t.Iterator[t.Any]:
        """Batching helper can be wrapped as a dlt.resource

        Returns:
            Iterator[Any]: yields scraped items one by one
        """
        batch: t.List[T] = []
        while True:
            if len(batch) == self.batch_size:
                yield batch
                batch = []

            try:
                if self.is_closed:
                    try:
                        item = self.get_nowait()
                    except Empty:
                        raise QueueClosedError("Queue is closed")
                else:
                    item = self.get(timeout=self.read_timeout)
                batch.append(item)

                # Mark task as completed
                self.task_done()
            except Empty:
                if batch:
                    yield batch
                    batch = []
            except QueueClosedError:
                logger.info("Queue is closed and drained")

                if batch:
                    yield batch

                break

    def stream(self) -> t.Iterator[t.Any]:
        """Streaming generator, wraps get_batches
        and handles `GeneratorExit` if dlt closes it.

        Returns:
            t.Iterator[t.Any]: returns batches of scraped content
        """
        try:
            yield from self.get_batches()
        except GeneratorExit:
            self.close()

    def close(self) -> None:
        """Marks queue as closed"""
        self._is_closed = True

    @property
    def is_closed(self) -> bool:
        return self._is_closed

"""Worker classes for the tests of `worker_pool`, loaded in worker processes from this file"""

import os
import sys
from typing import Any, Dict, Iterator, Optional, Tuple

import pyarrow


class EchoWorker:
    """Streams a ticket back: a list of `(values, metadata)`, `values` None sends only metadata.
    A string ticket is raised as an error, "exit" ends the process."""

    def do_get(self, ticket: Any) -> Iterator[Tuple[Optional[Any], Dict[str, Any]]]:
        if ticket == "exit":
            os._exit(3)
        if isinstance(ticket, str):
            raise ValueError(ticket)
        for values, metadata in ticket:
            table = None if values is None else pyarrow.table({"n": values})
            yield table, {
                **metadata,
                "pid": os.getpid(),
                "modules": sorted(m for m in ("dlt", "sources") if m in sys.modules),
            }

