class MySpider(Spider):
    def parse(self, response: Response, **kwargs: Any) -> Any:
        for next_page in response.css("li.next a::attr(href)"):
            if next_page:
                yield response.follow(next_page, self.parse)

        for quote in response.css("div.quote"):
            result = {
                "quote": {
                    "text": quote.css("span.text::text").get(),
                    "author": quote.css("small.author::text").get(),
                    "tags": quote.css("div.tags a.tag::text").getall(),
                },
            }

            yield result


class MockQueue(ScrapingQueue):
    """Test queue alters the default get_batches behavior by
    adding max attempts count on queue read timeout
    """

    def __init__(
        self, maxsize: int = 0, batch_size: int = 10, read_timeout: float = 1.0
    ) -> None:
        super().__init__(maxsize, batch_size, read_timeout)
        self.max_empty_get_attempts = 5

    def get_batches(self) -> Iterator[Any]:
        batch: List = []
        get_attempts: int = 0
        while True:
            if len(batch) == self.batch_size:
                yield batch
                batch = []

            try:
                if self.is_closed:
                    try:
                        item = self.get_nowait()
                    except Empty:
                        raise QueueClosedError("Queue is closed")
                else:
                    item = self.get(timeout=self.read_timeout)
                batch.append(item)

                # Mark task as completed
                self.task_done()
            except Empty:
                if batch:
                    yield batch
                    batch = []

                if get_attempts >= self.max_empty_get_attempts:
                    self.close()
                    break

                print("Get attempt #", get_attempts)
                get_attempts += 1
            except QueueClosedError:
                if batch:
                    yield batch

                break


def queue_closer(
    queue: ScrapingQueue, close_after_seconds: float = 1.0
) -> threading.Thread:
    def close_queue():
        slept: int = 0
        while True:
            time.sleep(1)
            slept += 1
            if queue.is_closed:
                break

            if slept >= close_after_seconds:
                queue.close()
                break

    closer = threading.Thread(target=close_queue)
    closer.start()
    return closer


def table_expect_at_least_n_records(table_name: str, n: int, pipeline: dlt.Pipeline):
    with pipeline.sql_client() as client:
        with client.execute_query(f"SELECT count(*) FROM {table_name}") as cursor:
            count = cursor.fetchone()[0]
            assert count >= n, f"Expected at least {n} records, got {count}"

"""Checks that each source changed against the base branch bumps its version and adds a changelog
entry to its README, except for a patch version. Sources whose files did not change, or that
changed only their README, are skipped. See
`.claude/skills/refresh-source/SKILL.md#source-version-and-readme`.

The base branch is `SOURCES_BASE_REF` if set, `origin/<GITHUB_BASE_REF>` on pull requests,
otherwise `origin/master` or `master`. Run from the repository root:

    uv run python tools/check_source_versions.py
"""

import ast
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import List, Optional, Sequence, Set, Tuple

SOURCES_DIR = "sources"
VERSION_FILE = "version.py"
README_FILE = "README.md"
INITIAL_VERSION = "1.0.0"
GUIDE = ".claude/skills/refresh-source/SKILL.md#source-version-and-readme"
VERSION_PATTERN = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")

TVersion = Tuple[int, int, int]


def git(root: Path, *args: str) -> str:
    return subprocess.run(
        ["git", *args], cwd=root, check=True, capture_output=True, text=True
    ).stdout


def resolve_base(root: Path) -> str:
    """Returns the merge base of HEAD and the base branch"""
    github_base = os.environ.get("GITHUB_BASE_REF")
    refs = [
        ref
        for ref in dict.fromkeys(
            [
                os.environ.get("SOURCES_BASE_REF"),
                f"origin/{github_base}" if github_base else None,
                "origin/master",
                "master",
            ]
        )
        if ref
    ]
    for ref in refs:
        exists = subprocess.run(
            ["git", "rev-parse", "--verify", "--quiet", f"{ref}^{{commit}}"],
            cwd=root,
            capture_output=True,
        )
        if exists.returncode == 0:
            return git(root, "merge-base", ref, "HEAD").strip()
    raise RuntimeError(
        f"No base branch found among {[ref for ref in refs if ref]}, fetch it with"
        " `git fetch origin master` or set SOURCES_BASE_REF"
    )


def changed_paths(root: Path, base: str) -> Set[str]:
    """Paths under `sources` changed since `base`, including uncommitted and untracked files"""
    tracked = git(root, "diff", "--name-only", base, "--", SOURCES_DIR)
    untracked = git(root, "ls-files", "--others", "--exclude-standard", SOURCES_DIR)
    return set(tracked.splitlines()) | set(untracked.splitlines())


def changed_sources(paths: Sequence[str]) -> Set[str]:
    """Names of source folders with changes to files other than their README"""
    names: Set[str] = set()
    for path in paths:
        parts = path.split("/")
        if (
            len(parts) > 2
            and parts[0] == SOURCES_DIR
            and not parts[1].startswith((".", "_"))
            and parts[2:] != [README_FILE]
        ):
            names.add(parts[1])
    return names


def parse_version(code: str) -> TVersion:
    """Returns the `__version__` assigned in `code`.

    Raises ValueError if it is missing or not MAJOR.MINOR.PATCH.
    """
    for node in ast.parse(code).body:
        if not isinstance(node, ast.Assign) or not any(
            isinstance(target, ast.Name) and target.id == "__version__"
            for target in node.targets
        ):
            continue
        value = node.value.value if isinstance(node.value, ast.Constant) else None
        match = VERSION_PATTERN.match(value) if isinstance(value, str) else None
        if match is None:
            raise ValueError("`__version__` is not a MAJOR.MINOR.PATCH string")
        major, minor, patch = (int(part) for part in match.groups())
        return major, minor, patch
    raise ValueError("there is no `__version__` assignment")


def format_version(version: TVersion) -> str:
    return ".".join(str(part) for part in version)


def has_changelog_entry(readme: str, version: str) -> bool:
    """Tells if `readme` has a heading that starts with `version`, e.g. `### 1.2.0`"""
    pattern = rf"^#+\s+v?{re.escape(version)}(?![\d.])"
    return re.search(pattern, readme, re.MULTILINE) is not None


def base_file(root: Path, base: str, path: str) -> Optional[str]:
    """Returns the content of `path` at `base`, None if it does not exist there"""
    result = subprocess.run(
        ["git", "show", f"{base}:{path}"], cwd=root, capture_output=True, text=True
    )
    return result.stdout if result.returncode == 0 else None


def check_source(root: Path, base: str, name: str, paths: Set[str]) -> List[str]:
    """Returns the problems with the version and the README of a changed source"""
    source_dir = f"{SOURCES_DIR}/{name}"
    if not (root / source_dir / "__init__.py").is_file():
        # the source was removed
        return []
    errors: List[str] = []
    version_path = f"{source_dir}/{VERSION_FILE}"
    version: Optional[TVersion] = None
    if not (root / version_path).is_file():
        errors.append(f'add {version_path} with `__version__ = "{INITIAL_VERSION}"`')
    else:
        try:
            version = parse_version((root / version_path).read_text(encoding="utf-8"))
        except (ValueError, SyntaxError) as ex:
            errors.append(f"{version_path}: {ex}")
    base_code = base_file(root, base, version_path)
    base_version: Optional[TVersion] = None
    if version and base_code is not None:
        try:
            base_version = parse_version(base_code)
        except (ValueError, SyntaxError):
            pass
        if base_version and version <= base_version:
            errors.append(
                f"bump the version in {version_path}, it is"
                f" {format_version(base_version)} on the base branch: major for breaking"
                " changes, minor for features, patch for fixes"
            )
    # a fix released as a patch version needs no changelog entry
    if (
        version
        and base_version
        and version > base_version
        and version[:2] == base_version[:2]
    ):
        return errors
    readme_path = f"{source_dir}/{README_FILE}"
    if not (root / readme_path).is_file():
        errors.append(f"add {readme_path} with a changelog")
        return errors
    if readme_path not in paths:
        errors.append(f"update {readme_path}: add a changelog entry for the change")
    elif version and not has_changelog_entry(
        (root / readme_path).read_text(encoding="utf-8"), format_version(version)
    ):
        errors.append(
            f"add a changelog entry `### {format_version(version)}` to {readme_path}"
        )
    return errors


def main(root: Path) -> int:
    base = resolve_base(root)
    paths = changed_paths(root, base)
    sources = sorted(changed_sources(sorted(paths)))
    failed = False
    for name in sources:
        for error in check_source(root, base, name, paths):
            print(f"ERROR: Source {name}: {error}")
            failed = True
    if failed:
        print(f"Changed sources must bump their version and changelog, see {GUIDE}")
        return 1
    print(f"Versions and changelogs of changed sources are up to date: {sources}")
    return 0


if __name__ == "__main__":
    sys.exit(main(Path(git(Path.cwd(), "rev-parse", "--show-toplevel").strip())))

"""Parses raw BSON into Arrow tables. Worker processes import this module, so it does not
import dlt."""

import warnings
from functools import cache
from inspect import signature
from typing import (
    Any,
    Dict,
    Iterable,
    Iterator,
    List,
    NamedTuple,
    Optional,
    Set,
    Tuple,
)

import pyarrow
import pyarrow.compute
from bson import decode_all
from pymongo import MongoClient
from pymongoarrow.context import PyMongoArrowContext  # type: ignore
from pymongoarrow.schema import Schema  # type: ignore
from pymongoarrow.types import (  # type: ignore
    _is_binary,
    _is_code,
    _is_decimal128,
    _is_objectid,
)

from .partition import TPartition, find_partition
from .worker_pool import ArrowWorker, TTableWithMetadata


class Mismatch(NamedTuple):
    """Fields with values that do not match their type, `a.b` for nested fields"""

    fields: Dict[str, List[str]]
    details: str
    with_schema: bool


def parse_bson_batches(
    batches: Iterable[bytes],
    pymongoarrow_schema: Any,
    codec_options: Any,
    strict: bool = False,
) -> Any:
    """Parses raw BSON batches into one table with the BSON extension types of pymongoarrow.
    With `strict`, values that do not match `pymongoarrow_schema` raise `TypeError`."""
    # pymongoarrow 1.6 replaced `from_schema` and `lib.process_bson_stream` and stopped resetting
    # the context on `finish()`
    if hasattr(PyMongoArrowContext, "from_schema"):
        from pymongoarrow.lib import process_bson_stream  # type: ignore

        context = PyMongoArrowContext.from_schema(
            schema=pymongoarrow_schema, codec_options=codec_options
        )
        for batch in batches:
            process_bson_stream(batch, context)
    else:
        kwargs = {"allow_invalid": not strict} if _supports_strict_schema() else {}
        context = PyMongoArrowContext(
            pymongoarrow_schema, codec_options=codec_options, **kwargs
        )
        for batch in batches:
            context.process_bson_stream(batch)
    return context.finish()


def parse_batch(
    batches: List[bytes],
    pymongoarrow_schema: Any,
    codec_options: Any,
    detect_mismatch: bool,
) -> Tuple[Any, Optional[Mismatch]]:
    """Parses raw BSON batches into a table with Arrow types, and finds the fields with values of
    more than one type. Returns no table when values do not match `pymongoarrow_schema`.
    """
    if pymongoarrow_schema is not None:
        try:
            table = parse_bson_batches(
                batches,
                pymongoarrow_schema,
                codec_options,
                strict=_supports_strict_schema(),
            )
        except TypeError as ex:
            return None, Mismatch(
                _mismatched_fields(batches, codec_options), str(ex), True
            )
        return convert_arrow_columns(table), None

    table = parse_bson_batches(batches, None, codec_options)
    mismatch = None
    if detect_mismatch and _supports_strict_schema():
        # the inferred schema loads values of another type as null, a strict one raises
        inferred = Schema({field.name: field.type for field in table.schema})
        try:
            parse_bson_batches(batches, inferred, codec_options, strict=True)
        except TypeError as ex:
            mismatch = Mismatch(
                _mismatched_fields(batches, codec_options), str(ex), False
            )
    return convert_arrow_columns(table), mismatch


def read_partition(
    collection: Any,
    partition: TPartition,
    filter_: Dict[str, Any],
    projection: Optional[Dict[str, Any]],
    pymongoarrow_schema: Any,
    detect_mismatch: bool,
) -> Tuple[Any, Optional[Mismatch]]:
    """Parses the documents of `partition` that match `filter_` into one table"""
    # one parse of all batches infers one type for each field
    batches = list(
        find_partition(collection.find_raw_batches, partition, filter_, projection)
    )
    return parse_batch(
        batches, pymongoarrow_schema, collection.codec_options, detect_mismatch
    )


def convert_arrow_columns(table: Any) -> Any:
    """Converts the BSON extension types of pymongoarrow to Arrow types, also in nested columns"""
    for i, field in enumerate(table.schema):
        column = table.column(i)
        chunks = [_convert_arrow_array(chunk) for chunk in column.chunks]
        if all(chunk is original for chunk, original in zip(chunks, column.chunks)):
            continue
        table = table.set_column(
            i,
            pyarrow.field(field.name, chunks[0].type, field.nullable),
            pyarrow.chunked_array(chunks),
        )
    return table


class MongoArrowWorker(ArrowWorker):
    """Reads a partition of a collection into one table"""

    def __init__(self) -> None:
        self._clients: Dict[str, Any] = {}

    def do_get(self, ticket: Dict[str, Any]) -> Iterator[TTableWithMetadata]:
        url = ticket["connection_url"]
        if url not in self._clients:
            with warnings.catch_warnings():
                # see `ignore_compressor_warnings` in helpers.py
                warnings.filterwarnings("ignore", "Wire protocol compression with")
                warnings.filterwarnings("ignore", "Unsupported compressor: $")
                self._clients[url] = MongoClient(url, **ticket["client_options"])
        collection = self._clients[url][ticket["database"]][ticket["collection"]]
        table, mismatch = read_partition(
            collection,
            ticket["partition"],
            ticket["filter"],
            ticket["projection"],
            ticket["pymongoarrow_schema"],
            ticket["detect_mismatch"],
        )
        yield table, {"mismatch": mismatch and mismatch._asdict()}


@cache
def _supports_strict_schema() -> bool:
    return "allow_invalid" in signature(PyMongoArrowContext.__init__).parameters


def _mismatched_fields(
    batches: List[bytes], codec_options: Any
) -> Dict[str, List[str]]:
    """Names the fields with values of more than one type, `a.b` for nested ones"""
    types: Dict[str, Set[str]] = {}

    def visit(value: Any, path: str) -> None:
        if value is None:
            return
        if isinstance(value, dict):
            type_name = "document"
            for key, item in value.items():
                visit(item, f"{path}.{key}")
        elif isinstance(value, list):
            type_name = "array"
            for item in value:
                visit(item, f"{path}[]")
        elif isinstance(value, int) and not isinstance(value, bool):
            type_name = "int"
        else:
            type_name = type(value).__name__
        types.setdefault(path, set()).add(type_name)

    for batch in batches:
        for document in decode_all(batch, codec_options):
            for key, value in document.items():
                visit(value, key)
    return {path: sorted(names) for path, names in types.items() if len(names) > 1}


def _convert_arrow_array(array: Any) -> Any:
    """Converts the BSON extension types in `array`, returns `array` itself if there are none"""
    arrow_type = array.type
    if _is_objectid(arrow_type):
        # the hex string of the "python" backend
        return _objectid_to_hex(array.storage)
    if _is_decimal128(arrow_type):
        # there's no vectorized decoding of BSON decimals
        return pyarrow.array(
            [None if value is None else str(value) for value in array.to_pylist()],
            type=pyarrow.string(),
        )
    if _is_binary(arrow_type) or _is_code(arrow_type):
        return array.storage

    if not pyarrow.types.is_struct(arrow_type) and not pyarrow.types.is_list(
        arrow_type
    ):
        return array
    if array.offset:
        # nested arrays are not rebuilt from sliced offsets together with a null mask
        array = pyarrow.concat_arrays([array])
    if pyarrow.types.is_struct(arrow_type):
        children = array.flatten()
        converted = [_convert_arrow_array(child) for child in children]
        if all(new is old for new, old in zip(converted, children)):
            return array
        return pyarrow.StructArray.from_arrays(
            converted,
            fields=[
                pyarrow.field(field.name, child.type, field.nullable)
                for field, child in zip(arrow_type, converted)
            ],
            mask=array.is_null(),
        )
    values = _convert_arrow_array(array.values)
    if values is array.values:
        return array
    return pyarrow.ListArray.from_arrays(array.offsets, values, mask=array.is_null())


@cache
def _hex_octets() -> Any:
    return pyarrow.array([f"{octet:02x}" for octet in range(256)])


def _objectid_to_hex(storage: Any) -> Any:
    """Vectorized `str(ObjectId)` of a `fixed_size_binary[12]` array"""
    if len(storage) == 0:
        return pyarrow.array([], type=pyarrow.string())
    width = storage.type.byte_width
    octets = pyarrow.Array.from_buffers(
        pyarrow.uint8(),
        len(storage) * width,
        [None, storage.buffers()[1]],
        offset=storage.offset * width,
    )
    pairs = pyarrow.FixedSizeListArray.from_arrays(
        pyarrow.compute.take(_hex_octets(), octets), width, mask=storage.is_null()
    )
    return pyarrow.compute.binary_join(pairs.cast(pyarrow.list_(pyarrow.string())), "")

"""Worker processes that run tasks of threads and stream Arrow tables back, like `do_get` of
Arrow Flight. A worker process runs this file by path, so it imports neither dlt nor its package."""

import errno
import importlib
import json
import operator
import os
import pickle
import signal
import struct
import subprocess
import sys
import threading
import traceback
import types
import weakref
from enum import IntEnum
from typing import IO, Any, Dict, Iterator, Optional, Tuple, Type

import pyarrow
import pyarrow.ipc

TWorkerSpec = Tuple[str, str, str]
TTableWithMetadata = Tuple[Optional[Any], Optional[Dict[str, Any]]]

# a message is its kind, the sizes of its JSON metadata and body, the metadata and the body
_PREFIX = struct.Struct(">BIQ")
_BOOTSTRAP = (
    "import json, runpy, sys; sys.path[:] = json.loads(sys.argv[1]); "
    "runpy.run_path(sys.argv[2], run_name='__main__')"
)
# directories of worker classes imported as packages, see `load_worker`
_PACKAGES: Dict[str, str] = {}


class MessageKind(IntEnum):
    """The parent sends tasks, a worker answers each with tables and done or error"""

    # ASCII letters are readable in a dump of the pipes
    TASK = ord("T")
    TABLE = ord("A")
    DONE = ord("D")
    ERROR = ord("E")


class ArrowWorker:
    """Streams the Arrow tables of a ticket from a worker process. A process creates one instance
    and keeps it between tickets."""

    def do_get(self, ticket: Any) -> Iterator[TTableWithMetadata]:
        """Yields the tables of `ticket`, each with JSON serializable metadata. A None table sends
        only metadata."""
        raise NotImplementedError()


class WorkerError(Exception):
    pass


class WorkerProcess:
    """A worker process of the current Python interpreter, runs one ticket at a time"""

    def __init__(self) -> None:
        self.process = subprocess.Popen(
            [
                sys.executable,
                "-c",
                _BOOTSTRAP,
                json.dumps(sys.path),
                os.path.abspath(__file__),
            ],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
        )
        self._finalizer = weakref.finalize(self, _close_process, self.process)

    @property
    def alive(self) -> bool:
        return self._finalizer.alive and self.process.poll() is None

    def do_get(
        self, worker: Type[ArrowWorker], ticket: Any
    ) -> Iterator[TTableWithMetadata]:
        """Streams the tables of `ticket` from `worker` in this process"""
        done = False
        try:
            try:
                write_message(
                    self.process.stdin,
                    MessageKind.TASK,
                    worker_spec(worker),
                    pickle.dumps(ticket),
                )
            except OSError as ex:
                if not _is_closed_pipe(ex):
                    raise
                raise self._exited()
            while True:
                try:
                    kind, metadata, body = read_message(self.process.stdout)
                except EOFError:
                    raise self._exited()
                if kind == MessageKind.TABLE:
                    yield _table_from_ipc(body), metadata
                    continue
                done = True
                if kind == MessageKind.ERROR:
                    raise WorkerError(metadata)
                return
        finally:
            # the rest of an unread stream comes with the next ticket
            if not done:
                self.close()

    def close(self) -> None:
        self._finalizer()

    def _exited(self) -> WorkerError:
        return WorkerError(f"Worker process exited with code {self.process.wait()}")


class WorkerPool:
    """One worker process for each thread, started on first use and closed when the thread ends"""

    def __init__(self) -> None:
        self._local = threading.local()
        self._processes: "weakref.WeakSet[WorkerProcess]" = weakref.WeakSet()
        self._lock = threading.Lock()

    def do_get(
        self, worker: Type[ArrowWorker], ticket: Any
    ) -> Iterator[TTableWithMetadata]:
        """Streams the tables of `ticket` from `worker` in the process of the current thread"""
        return self._process().do_get(worker, ticket)

    def close(self) -> None:
        """Closes the processes of all threads"""
        with self._lock:
            processes = list(self._processes)
        for process in processes:
            process.close()

    def __enter__(self) -> "WorkerPool":
        return self

    def __exit__(self, *_: Any) -> None:
        self.close()

    def _process(self) -> WorkerProcess:
        holder: Optional[_ThreadProcess] = getattr(self._local, "holder", None)
        if holder is None or not holder.process.alive:
            holder = self._local.holder = _ThreadProcess(WorkerProcess())
            with self._lock:
                self._processes.add(holder.process)
        return holder.process


class _ThreadProcess:
    """Closes the process when the thread ends, also when a traceback still refers to the process"""

    __slots__ = ("process", "__weakref__")

    def __init__(self, process: WorkerProcess) -> None:
        self.process = process
        weakref.finalize(self, process.close)


def worker_spec(worker: Type[ArrowWorker]) -> TWorkerSpec:
    """The directory, module and class name that a worker process loads `worker` from"""
    path = getattr(sys.modules[worker.__module__], "__file__", None)
    if worker.__module__ == "__main__" or not path:
        raise ValueError(
            f"Worker `{worker.__qualname__}` must be defined in a module file"
        )
    directory, file_name = os.path.split(os.path.abspath(path))
    return directory, os.path.splitext(file_name)[0], worker.__qualname__


def load_worker(directory: str, module: str, name: str) -> Type[ArrowWorker]:
    """Imports a worker class from its module in `directory`"""
    # the directory becomes a package without its `__init__`, relative imports of the module work
    package = _PACKAGES.get(directory)
    if package is None:
        package = _PACKAGES[directory] = f"_worker_package_{len(_PACKAGES)}"
        package_module = types.ModuleType(package)
        package_module.__path__ = [directory]
        sys.modules[package] = package_module
    worker: Type[ArrowWorker] = operator.attrgetter(name)(
        importlib.import_module(f"{package}.{module}")
    )
    return worker


def serve() -> None:
    """Runs the tickets from stdin and writes their tables to stdout until stdin closes"""
    # the parent stops its workers on ctrl-c
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    output = sys.stdout.buffer
    # stray prints corrupt the messages
    sys.stdout = sys.stderr
    workers: Dict[TWorkerSpec, ArrowWorker] = {}
    while True:
        try:
            _, worker, ticket = read_message(sys.stdin.buffer)
        except EOFError:
            return
        try:
            spec: TWorkerSpec = tuple(worker)
            if spec not in workers:
                workers[spec] = load_worker(*spec)()
            # tickets come only from the parent process that started this one
            for table, metadata in workers[spec].do_get(pickle.loads(ticket)):
                write_message(output, MessageKind.TABLE, metadata, _table_to_ipc(table))
        except Exception:
            write_message(output, MessageKind.ERROR, traceback.format_exc())
        else:
            write_message(output, MessageKind.DONE)


def write_message(
    stream: IO[bytes], kind: MessageKind, metadata: Any = None, body: Any = b""
) -> None:
    """Writes a message of `kind` with JSON serializable `metadata` and a `body` of bytes"""
    encoded = json.dumps(metadata).encode()
    body = memoryview(body)
    stream.write(_PREFIX.pack(kind, len(encoded), body.nbytes))
    stream.write(encoded)
    stream.write(body)
    stream.flush()


def read_message(stream: IO[bytes]) -> Tuple[MessageKind, Any, bytes]:
    """Reads the kind, metadata and body of a message. Raises `EOFError` when the stream ends."""
    kind, metadata_size, body_size = _PREFIX.unpack(_read_exact(stream, _PREFIX.size))
    metadata = json.loads(_read_exact(stream, metadata_size))
    return MessageKind(kind), metadata, _read_exact(stream, body_size)


def _close_process(process: "subprocess.Popen[bytes]") -> None:
    if process.poll() is None:
        process.kill()
    process.wait()
    try:
        process.stdin.close()
    except OSError as ex:
        # a task left in the buffer of a dead worker
        if not _is_closed_pipe(ex):
            raise
    process.stdout.close()


def _is_closed_pipe(ex: OSError) -> bool:
    """Writing to the pipe of an exited process, Windows raises EINVAL like in `subprocess`"""
    return isinstance(ex, BrokenPipeError) or ex.errno == errno.EINVAL


def _table_to_ipc(table: Any) -> Any:
    if table is None:
        return b""
    sink = pyarrow.BufferOutputStream()
    with pyarrow.ipc.new_stream(sink, table.schema) as writer:
        writer.write_table(table)
    return sink.getvalue()


def _table_from_ipc(body: bytes) -> Any:
    if not body:
        return None
    return pyarrow.ipc.open_stream(pyarrow.py_buffer(body)).read_all()


def _read_exact(stream: IO[bytes], size: int) -> bytes:
    data = stream.read(size)
    if len(data) != size:
        raise EOFError(f"stream ended after {len(data)} of {size} bytes")
    return data


if __name__ == "__main__":
    serve()

from typing import Any, List, Optional

from langchain.base_language import BaseLanguageModel
from langchain.chains.retrieval_qa.base import RetrievalQA
from langchain.indexes.vectorstore import (
    VectorstoreIndexCreator,
    VectorStoreIndexWrapper,
)
from langchain.llms.openai import OpenAI
from langchain.schema import Document


class AVectorStoreIndexWrapper(VectorStoreIndexWrapper):
    """Async wrapper around a vectorstore for easy access."""

    def __init__(
        self,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)

    async def aquery(
        self, question: str, llm: Optional[BaseLanguageModel] = None, **kwargs: Any
    ) -> str:
        """Query the vectorstore."""
        llm = llm or OpenAI(temperature=0)  # type: ignore[call-arg]
        chain = RetrievalQA.from_chain_type(
            llm, retriever=self.vectorstore.as_retriever(), **kwargs
        )
        return str(await chain.arun(question))


class AVectorstoreIndexCreator(VectorstoreIndexCreator):
    """Async logic for creating indexes."""

    def from_documents(self, documents: List[Document]) -> AVectorStoreIndexWrapper:
        """Create a vectorstore index from documents."""
        sub_docs = self.text_splitter.split_documents(documents)
        vectorstore = self.vectorstore_cls.from_documents(
            sub_docs, self.embedding, **self.vectorstore_kwargs
        )
        return AVectorStoreIndexWrapper(vectorstore=vectorstore)
